import java.sql.*;

public class SecureExample {
    public void login(String username, String password) throws SQLException {
        Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/db", "user", "pass");

        // Use PreparedStatement to prevent SQL Injection by using parameterized queries.
        // The '?' characters act as placeholders for the data.
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";

        PreparedStatement pstmt = conn.prepareStatement(query);

        // The JDBC driver ensures that these inputs are treated strictly as literal values (data),
        // not as executable SQL code, regardless of what characters they contain.
        pstmt.setString(1, username);
        pstmt.setString(2, password);

        ResultSet rs = pstmt.executeQuery();

        if (rs.next()) {
            System.out.println("Login successful!");
        }
    }
}
